  assert.equal(await c.get('a', load, ['user:1']), 1);
  v = 2;
  t = 150;
  assert.equal(await c.get('a', load), 1, 'stale, served at once');
  await new Promise((r) => setImmediate(r));
  assert.equal(await c.get('a', load), 2, 'refreshed behind the scenes');
  t = 1000;
